  const limit=paris(new Date(now.getTime()-3*3600000));
  for(const job of queue.filter(r=>['radar_run','seo_scan','content_batch'].includes(r.type)&&r.status==='ready'&&r.due_at&&r.due_at.slice(0,19).replace('T',' ')<=limit)) {
